45	void warp_t::reset() {
46	  this->tmask.reset();
47	  this->PC   = 0;
48	  this->uuid = 0;
49	  this->fcsr = 0;
50	  this->mstatus = 0;
51	  this->mtvec   = 0;
52	  this->mepc    = 0;
53	  this->mcause  = 0;
54	  this->mtval   = 0;
55	  this->mscratch_tmask.reset();
56	  // Register files live in OpcUnit and are reset there.
57	}
