61	Scheduler::Scheduler(const SimContext& ctx, const char* name, Core* core)
62	    : SimObject<Scheduler>(ctx, name)
63	    , core_(core)
64	    , warps_(VX_CFG_NUM_WARPS, VX_CFG_NUM_THREADS)
65	    , in_async_trap_(VX_CFG_NUM_WARPS, false)
66	    , trap_epoch_(VX_CFG_NUM_WARPS, 0)
67	    , last_mret_cycle_(VX_CFG_NUM_WARPS, 0)
68	    , async_trap_snapshot_(VX_CFG_NUM_WARPS)
69	    , ipdom_size_(VX_CFG_NUM_THREADS - 1)
70	{
71	  std::srand(50);
72	
73	  // create child SimObjects (CTA dispatcher + barrier unit). Both are
74	  // registered with SimPlatform and get their own do_reset()/do_tick() calls.
75	  char sname[128];
76	  snprintf(sname, sizeof(sname), "%s-cta", name);
77	  cta_dispatcher_ = SimPlatform::instance().create_object<CtaDispatcher>(sname, core);
78	  snprintf(sname, sizeof(sname), "%s-barrier", name);
79	  barrier_unit_ = SimPlatform::instance().create_object<BarrierUnit>(sname, core, this);
80	
81	#ifdef VX_CFG_EXT_RASTER_ENABLE
82	  fwd_is_fragment_.assign(VX_CFG_NUM_WARPS, false);
83	#endif
84	}
