88	void Scheduler::on_reset() {
89	  for (auto& warp : warps_) {
90	    warp.reset();
91	  }
92	
93	  stalled_warps_.reset();
94	  stalled_warps_next_.reset();
95	  active_warps_.reset();
96	  std::fill(in_async_trap_.begin(), in_async_trap_.end(), false);
97	  std::fill(trap_epoch_.begin(), trap_epoch_.end(), 0);
98	  // Sequencers live on Core now; Core::on_reset() resets them.
99	  wspawn_.valid = false;
100	
101	#ifdef VX_CFG_EXT_RASTER_ENABLE
102	  fwd_armed_   = false;
103	  fwd_drained_ = false;
104	  fwd_launched_ = 0;
105	  fwd_retired_  = 0;
106	  fwd_reqs_outstanding_ = 0;
107	  std::queue<FwdWave> empty;
108	  std::swap(fwd_waves_, empty);
109	  std::fill(fwd_is_fragment_.begin(), fwd_is_fragment_.end(), false);
110	#endif
111	
112	  // cta_dispatcher_ and barrier_unit_ are SimObjects — SimPlatform calls
113	  // their do_reset() directly.
114	}
