116	void Scheduler::activate_warp(uint32_t wid, const cta_warp_record_t& rec) {
117	  auto& warp = warps_[wid];
118	
119	  // Reusing a warp for the next CTA skips the one-time prologue and rewinds to
120	  // the kernel's per-CTA dispatch window — a fixed 20-byte (5-instruction)
121	  // sequence that reloads the entry pointer and kargs before re-calling.
122	  warp.PC       = rec.do_init ? rec.PC : (warp.PC - 20);
123	  warp.tmask    = rec.tmask;
124	  warp.mscratch = rec.mscratch;
125	
126	  warp.cta_csrs.cta_id        = rec.cta_id;
127	  warp.cta_csrs.cta_rank      = rec.cta_rank;
128	  warp.cta_csrs.cta_size      = rec.cta_size;
129	  warp.cta_csrs.thread_idx[0] = rec.thread_idx[0];
130	  warp.cta_csrs.thread_idx[1] = rec.thread_idx[1];
131	  warp.cta_csrs.thread_idx[2] = rec.thread_idx[2];
132	  warp.cta_csrs.block_idx[0]  = rec.block_idx[0];
133	  warp.cta_csrs.block_idx[1]  = rec.block_idx[1];
134	  warp.cta_csrs.block_idx[2]  = rec.block_idx[2];
135	  warp.cta_csrs.block_dim[0]  = rec.block_dim[0];
136	  warp.cta_csrs.block_dim[1]  = rec.block_dim[1];
137	  warp.cta_csrs.block_dim[2]  = rec.block_dim[2];
138	  warp.cta_csrs.grid_dim[0]   = rec.grid_dim[0];
139	  warp.cta_csrs.grid_dim[1]   = rec.grid_dim[1];
140	  warp.cta_csrs.grid_dim[2]   = rec.grid_dim[2];
141	  warp.cta_csrs.entry         = rec.entry;
142	  warp.cta_csrs.lmem_addr     = rec.lmem_addr;
143	  warp.cta_csrs.cluster_size  = rec.cluster_size;
144	
145	  while (!warp.ipdom_stack.empty()) warp.ipdom_stack.pop();
146	
147	  active_warps_.set(wid);
148	  // CTA activation is not the registered suspend/resume path; clear both the
149	  // current and next stall state so the freshly-dispatched warp is immediately
150	  // schedulable (no spurious one-cycle stall from the registered state).
151	  stalled_warps_.reset(wid);
152	  stalled_warps_next_.reset(wid);
153	
154	  DP(3, "*** dispatch CTA warp: cid=" << core_->id()
155	     << ", wid=" << wid << ", cta_id=" << warp.cta_csrs.cta_id
156	     << ", rank=" << warp.cta_csrs.cta_rank << "/" << warp.cta_csrs.cta_size
157	     << ", tmask=" << warp.tmask
158	     << ", PC=0x" << std::hex << warp.PC << std::dec
159	     << ", blockIdx=(" << warp.cta_csrs.block_idx[0] << "," << warp.cta_csrs.block_idx[1] << ")"
160	     << ", mscratch=0x" << std::hex << warp.mscratch << std::dec);
161	}
162	
163	instr_trace_t* Scheduler::schedule(const WarpMask& warp_mask) {
164	  int scheduled_warp = -1;
165	
166	  // Dispatch one CTA warp
167	  {
168	    uint32_t wid;
169	    cta_warp_record_t rec;
170	    if (cta_dispatcher_->step(active_warps_, &wid, &rec)) {
171	      activate_warp(wid, rec);
172	    }
173	  }
174	
175	#ifdef VX_CFG_EXT_RASTER_ENABLE
176	  // Inject ready fragment waves into free warp slots (RASTER dispatch v2).
177	  if (fwd_armed_)
178	    fwd_try_inject();
179	#endif
180	
181	  // process pending wspawn when we are down to a single active warp
182	  if (wspawn_.valid && active_warps_.count() == 1) {
183	    DP(3, "*** Activate " << (wspawn_.num_warps-1) << " warps at PC: " << std::hex << wspawn_.nextPC << std::dec);
184	    auto spawning_mscratch = warps_.at(0).mscratch;
185	    for (uint32_t i = 1; i < wspawn_.num_warps; ++i) {
186	      auto& warp = warps_.at(i);
187	      warp.PC = wspawn_.nextPC;
188	      warp.tmask.set(0);
189	      warp.mscratch = spawning_mscratch;
190	      active_warps_.set(i);
191	      // wspawn activation, like CTA dispatch: immediate (both current + next).
192	      stalled_warps_.reset(i);
193	      stalled_warps_next_.reset(i);
194	      DT(3, core_->name() << " warp-state: wid=" << i << ", active=true, stalled=false, tmask=" << warp.tmask);
195	    }
196	    wspawn_.valid = false;
197	    this->resume(0);
198	  }
199	
200	  // pick next ready warp
201	  for (size_t wid = 0, nw = VX_CFG_NUM_WARPS; wid < nw; ++wid) {
202	    if (active_warps_.test(wid) && !stalled_warps_.test(wid) && warp_mask.test(wid)) {
203	      scheduled_warp = wid;
204	      break;
205	    }
206	  }
207	
208	  instr_trace_t* trace = nullptr;
209	  if (scheduled_warp != -1) {
210	    // get scheduled warp
211	    auto& warp = warps_.at(scheduled_warp);
212	    assert(warp.tmask.any());
213	
214	    // Generate UUID
215	    uint64_t uuid = 0;
216	  #ifndef NDEBUG
217	    {
218	      uint32_t instr_id = warp.uuid++;
219	      uint32_t g_wid = core_->id() * VX_CFG_NUM_WARPS + scheduled_warp;
220	      uuid = (uint64_t(g_wid) << 32) | instr_id;
221	    }
222	  #endif
223	
224	    // Allocate trace with header (fetch reads instruction word into trace->code,
225	    // decode fills in the rest of the metadata).
226	    trace = core_->trace_pool().allocate(1);
227	    new (trace) instr_trace_t(uuid);
228	    trace->cid    = core_->id();
229	    trace->wid    = scheduled_warp;
230	    trace->cta_id = warp.cta_csrs.cta_id;
231	    trace->PC     = warp.PC;
232	    trace->tmask  = warp.tmask;
233	    // PRISM RTU §6/§8.6: stamp trap_epoch so advance_pc can discard
234	    // a stale post-trap fetch (trap-epoch trailing the warp's current
235	    // trap_epoch_) without clobbering the trap-set mtvec.
236	    trace->trap_epoch = trap_epoch_.at(scheduled_warp);
237	
238	    // PC is advanced at decode (+2 for RVC, +4 otherwise) — matches
239	    // RTL VX_scheduler updating warp_pcs on decode_sched_if.valid.
240	    // Branch/JAL/JALR commit later overrides warp.PC with the
241	    // resolved target.
242	
243	    // Suspend warp until decode resumes it (non-stalling) or commit (stalling).
244	    this->suspend(scheduled_warp);
245	  }
246	
247	  // Clock the registered warp-stall state. The suspend above, or a resume from
248	  // decode/commit/FU earlier this cycle, drives stalled_warps_next_ and only
249	  // becomes visible to the pick loop next cycle — so a warp released as its
250	  // instruction resolves is never re-scheduled the same cycle.
251	  stalled_warps_ = stalled_warps_next_;
252	  return trace;
253	}
