255	bool Scheduler::running() const {
256	  return active_warps_.any() || cta_dispatcher_->running()
257	#ifdef VX_CFG_EXT_RASTER_ENABLE
258	    || fwd_armed_
259	#endif
260	    ;
261	}
262	
263	// suspend()/resume() drive the next-state; schedule() clocks it into the
264	// registered stalled_warps_ at the end of the cycle, so the change is observed
265	// only next cycle. Asserts check the next-state being mutated, not the
266	// registered value.
267	void Scheduler::suspend(uint32_t wid) {
268	  assert(active_warps_.test(wid));
269	  assert(!stalled_warps_next_.test(wid));
270	  stalled_warps_next_.set(wid);
271	  DT(3, core_->name() << " warp-state: wid=" << wid << ", stalled=true");
272	}
273	
274	void Scheduler::resume(uint32_t wid) {
275	  assert(active_warps_.test(wid));
276	  assert(stalled_warps_next_.test(wid));
277	  stalled_warps_next_.reset(wid);
278	  DT(3, core_->name() << " warp-state: wid=" << wid << ", stalled=false");
279	}
280	
281	void Scheduler::advance_pc(const instr_trace_t* trace, uint32_t inc) {
282	  // Drop stale post-trap fetches. A trace whose trap_epoch trails the
283	  // warp's current epoch was scheduled BEFORE the most recent async
284	  // trap; if we let it advance warp.PC now we'd step past the
285	  // trap-set mtvec and the dispatcher's first instruction would never
286	  // execute (the bug that broke the Phase 5 MISS test).
287	  if (trace->trap_epoch != trap_epoch_.at(trace->wid)) {
288	    return;
289	  }
290	  warps_.at(trace->wid).PC += inc;
291	}
