293	bool Scheduler::setTmask(uint32_t wid, const ThreadMask& tmask) {
294	  auto& warp = warps_.at(wid);
295	  if (warp.tmask != tmask) {
296	    DT(3, core_->name() << " warp-state: wid=" << wid << ", tmask=" << tmask);
297	  }
298	  warp.tmask = tmask;
299	  // deactivate warp if no active threads
300	  if (!tmask.any()) {
301	    active_warps_.reset(wid);
302	#ifdef VX_CFG_EXT_RASTER_ENABLE
303	    // An injected fragment wave retiring closes one FWD epoch slot.
304	    if (fwd_is_fragment_[wid]) {
305	      fwd_is_fragment_[wid] = false;
306	      ++fwd_retired_;
307	    }
308	#endif
309	    cta_dispatcher_->warp_done(wid);
310	    return false;
311	  }
312	  return true;
313	}
