315	bool Scheduler::wspawn(uint32_t num_warps, Word nextPC) {
316	  num_warps = std::min<uint32_t>(num_warps, VX_CFG_NUM_WARPS);
317	  if (num_warps < 2 && active_warps_.count() == 1)
318	    return true; // nothing to do
319	  // schedule wspawn
320	  wspawn_.valid = true;
321	  wspawn_.num_warps = num_warps;
322	  wspawn_.nextPC = nextPC;
323	  return false;
324	}
