326	// Barrier handling lives in BarrierUnit. See barrier_unit.{h,cpp}.
327	
328	// RISC-V machine-mode synchronous exception cause codes (mcause).
329	// Standard 0..15; 24..31 reserved for custom by the privileged spec.
330	namespace {
331	  constexpr Word TRAP_CAUSE_BREAKPOINT   = 3;
332	  constexpr Word TRAP_CAUSE_ECALL_MMODE  = 11;
333	}
334	
335	void Scheduler::raise_trap(uint32_t wid, Word cause, Word trap_pc) {
336	  auto& warp = warps_.at(wid);
337	  warp.mepc   = trap_pc;
338	  warp.mcause = cause;
339	  warp.mtval  = 0;
340	  warp.mscratch_tmask = warp.tmask;
341	  // Redirect to the handler. Low 2 bits of mtvec are the MODE field;
342	  // v1 supports direct mode only, so mask them off.
343	  warp.PC = warp.mtvec & ~Word(3);
344	  DT(3, core_->name() << " trap: wid=" << wid << ", cause=" << cause
345	     << ", mepc=0x" << std::hex << trap_pc << ", mtvec=0x" << warp.mtvec << std::dec);
346	}
347	
348	void Scheduler::raise_async_trap(uint32_t wid, Word cause, Word trap_pc, const ThreadMask& new_tmask) {
349	  // Flush this warp's unissued instructions BEFORE the trap CSRs are
350	  // written, so the resume PC reflects the oldest flushed instruction
351	  // (where the warp will re-fetch on mret). Real RISC-V trap entry
352	  // flushes the pipeline for the trapping context; SimX needs the same
353	  // because otherwise ibuf_inflight stays pegged at IBUF_SIZE and the
354	  // post-trap fetch can't make progress.
355	  Word resume_pc = core_->flush_warp_pipeline(wid);
356	  if (resume_pc == 0) {
357	    // ibuffer was empty — use the caller's PC as-is.
358	    resume_pc = trap_pc;
359	  }
360	  this->raise_trap(wid, cause, resume_pc);
361	  auto& warp = warps_.at(wid);
362	  warp.tmask = new_tmask;
363	  in_async_trap_.at(wid) = true;
364	  // Re-activate the warp if a flushed wstall instruction had suspended it. A
365	  // macro-op (e.g. the WAIT2 hit-window GETWF/GETW, or TRACE2) sets fetch_stall,
366	  // which suspends the warp until that op commits; if the async trap flushes it
367	  // mid-flight it never commits, so its resume_warp never fires. The trap is
368	  // taking over the warp to run the dispatcher, so resume it here. Idempotent:
369	  // only resume if currently stalled.
370	  if (stalled_warps_next_.test(wid))
371	    this->resume(wid);
372	  // Lift the warp's outstanding scoreboard reservations (the parked
373	  // vx_rt_wait's rd) so the callback dispatcher can save/restore the full
374	  // register context without deadlocking on a reservation only its own
375	  // cb_ret can release. Re-installed at mret. (RTU callback-trap, §4.6.)
376	  async_trap_snapshot_.at(wid) = core_->scoreboard().snapshot_warp(wid);
377	  // Bump the per-warp trap epoch so any pre-trap fetch still in flight
378	  // (fetch_latch_ / pending icache rsp) can be detected at advance_pc
379	  // and discarded — its decoded trace.trap_epoch will be one behind.
380	  ++trap_epoch_.at(wid);
381	  DT(3, core_->name() << " async-trap: wid=" << wid
382	     << ", new_tmask=0x" << std::hex << warp.tmask.to_ulong() << std::dec
383	     << ", mepc=0x" << std::hex << warp.mepc << std::dec);
384	}
385	
386	void Scheduler::mret(uint32_t wid) {
387	  auto& warp = warps_.at(wid);
388	  warp.PC    = warp.mepc;
389	  // Only restore the trap-saved mask when a trap actually saved one. A trap is
390	  // always taken by at least one active thread, so mscratch_tmask is non-empty
391	  // after any raise_trap; it is empty only in the pre-trap startup state. A bare
392	  // MRET used purely as a privilege switch (e.g. the riscv-tests startup jumping
393	  // into the test via mepc) must leave the running mask intact rather than clear
394	  // it, which would deactivate the warp.
395	  if (warp.mscratch_tmask.any())
396	    warp.tmask = warp.mscratch_tmask;
397	  // Re-install the reservations lifted at trap entry so the resumed
398	  // kernel's vx_rt_get_after still stalls until the ray's TERMINAL lands.
399	  // The matching TERMINAL writeback is held off until in_async_trap clears
400	  // (SfuUnit), so the dispatcher's epilogue restore can't clobber the
401	  // status word.
402	  core_->scoreboard().restore_warp(async_trap_snapshot_.at(wid));
403	  async_trap_snapshot_.at(wid).clear();
404	  in_async_trap_.at(wid) = false;
405	  last_mret_cycle_.at(wid) = SimPlatform::instance().cycles();
406	  DT(3, core_->name() << " mret: wid=" << wid
407	     << ", mepc=0x" << std::hex << warp.mepc << std::dec
408	     << ", restored tmask=0x" << std::hex << warp.tmask.to_ulong() << std::dec);
409	}
