449	bool Scheduler::fwd_can_request() const {
450	  // Bound in-flight work to ~NUM_WARPS waves (queued + outstanding requests).
451	  return !fwd_drained_
452	      && (fwd_waves_.size() + fwd_reqs_outstanding_) < VX_CFG_NUM_WARPS;
