455	bool Scheduler::fwd_done() const {
456	  return fwd_armed_ && fwd_drained_ && fwd_waves_.empty()
457	      && (fwd_reqs_outstanding_ == 0)
458	      && (fwd_launched_ == fwd_retired_);
459	}
