464	
465	void Scheduler::fwd_try_inject() {
466	  // The warp begins at the program image base (where __vx_cta_entry is linked),
467	  // exactly as a KMU-launched CTA does; the per-CTA dispatch window reads
468	  // VX_CSR_CTA_ENTRY (= rec.entry, the FS function) and VX_CSR_MSCRATCH
469	  // (= rec.mscratch, the FS args) and calls into the shader. The image base
470	  // is the KMU's startup PC (set by the grid-less draw kick, persists across
471	  // SimPlatform reset); the FS entry/arg come from the RASTER_FRAG_* descriptor.
472	  const Word startup_pc =
473	    Word(core_->socket()->cluster()->processor()->kmu().startup_pc());
474	
475	  while (!fwd_waves_.empty()) {
476	    // Find any free warp slot — there is no driver warp to skip in the push model.
477	    int wid = -1;
478	    for (uint32_t w = 0; w < VX_CFG_NUM_WARPS; ++w) {
479	      if (!active_warps_.test(w)) { wid = int(w); break; }
480	    }
481	    if (wid < 0) break;  // no free slot this cycle
482	
483	    const FwdWave& wave = fwd_waves_.front();
484	
485	    cta_warp_record_t rec;  // ThreadMask member needs sizing; assigned below
486	    rec.do_init  = true;
487	    rec.PC       = startup_pc;                                         // image base (__vx_cta_entry)
488	    rec.entry    = fwd_frag_entry_;                                    // FS function entry (CTA_ENTRY)
489	    rec.mscratch = fwd_frag_param_;                                    // FS args pointer
490	    rec.param    = fwd_frag_param_;
491	    rec.cta_id   = 0;
492	    rec.cta_rank = 0;
493	    rec.cta_size = 1;
494	    rec.thread_idx[0] = rec.thread_idx[1] = rec.thread_idx[2] = 0;
495	    // block_idx carries the record slot: the FS reads its payload via GETWS
496	    // (regfile[block_idx]). SimX seeds the window at regfile[wid] (it knows the
497	    // minted wid directly), so the slot IS the wid here — mirrors the RTL, where
498	    // the raster unit seeds regfile[slot] and passes slot as block_idx.
499	    rec.block_idx[0]  = uint32_t(wid);
500	    rec.block_idx[1]  = rec.block_idx[2]  = 0;
501	    rec.block_dim[0]  = VX_CFG_NUM_THREADS; rec.block_dim[1] = 1; rec.block_dim[2] = 1;
502	    rec.grid_dim[0]   = rec.grid_dim[1]   = rec.grid_dim[2]   = 1;
503	    rec.lmem_addr     = uint64_t(VX_MEM_LMEM_BASE_ADDR) + uint64_t(wid) * kFwdPayloadStride;
504	    rec.cluster_size  = 1;
505	    rec.tmask         = wave.tmask;
506	
507	    activate_warp(uint32_t(wid), rec);
508	
509	    // Seed the per-lane payload into this warp's gfx register window (FWD-5,
510	    // zero-LMEM): the FS reads it back with GETW. Reuses the SFU window-stage
511	    // path the pull op used.
512	    core_->sfu_unit()->stage_fwd_window(uint32_t(wid), wave);
513	
514	    fwd_is_fragment_[wid] = true;
515	    ++fwd_launched_;
516	    fwd_waves_.pop();
517	  }
518	}
519	#endif // VX_CFG_EXT_RASTER_ENABLE
520

