26	  : SimObject<CtaDispatcher>(ctx, name)
27	  , core_(core)
28	  , kmu_(&core->socket()->cluster()->processor()->kmu())
29	  , num_threads_(VX_CFG_NUM_THREADS)
30	  , num_warps_(VX_CFG_NUM_WARPS)
31	  , lmem_base_(VX_MEM_LMEM_BASE_ADDR)
32	  , lmem_capacity_(1u << VX_CFG_LMEM_LOG_SIZE)
33	  , slot_rem_warps_(num_warps_, 0)
34	  , wid_to_slot_(num_warps_, num_warps_)  // num_warps_ = invalid/unassigned
35	  , tail_slot_(0)
36	  , has_cta_(false)
37	  , cur_slot_(0)
38	  , cta_size_(0)
39	  , rank_(0)
40	  , block_size_rem_(0)
41	  , lmem_addr_(0)
42	  , has_pending_(false)
43	  , cur_kernel_pc_(0)
44	  , warp_init_mask_(num_warps_, false)
45	{
46	  thread_idx_[0] = thread_idx_[1] = thread_idx_[2] = 0;
47	}
