49	CtaDispatcher::~CtaDispatcher() {}
50	
51	void CtaDispatcher::on_reset() {
52	  has_cta_    = false;
53	  has_pending_= false;
54	  tail_slot_  = 0;
55	  for (uint32_t i = 0; i < num_warps_; ++i) {
56	    slot_rem_warps_[i] = 0;
57	    wid_to_slot_[i]    = num_warps_;  // invalid
58	    warp_init_mask_[i] = false;
59	  }
60	  cur_kernel_pc_ = 0;
61	}
62	
63	uint32_t CtaDispatcher::usable_slots(uint32_t stride) const {
64	  if (stride == 0)
65	    return num_warps_;
66	  uint32_t fit = uint32_t(lmem_capacity_ / stride);
67	  if (fit > num_warps_) fit = num_warps_;
68	  if (fit == 0) fit = 1;  // a single CTA that barely exceeds capacity still gets one slot
69	  return fit;
70	}
71	
72	bool CtaDispatcher::step(const WarpMask& active_warps, uint32_t* wid_out, cta_warp_record_t* rec_out) {
73	  if (!has_cta_) {
74	    // Load next CTA: use stashed pending CTA if available, else request from KMU.
75	    if (!has_pending_) {
76	      if (!kmu_->step(&pending_cta_)) return false;
77	      has_pending_ = true;
78	    }
79	
80	    // Fixed-stride admission. Round the per-CTA LMEM size up to a
81	    // MEM_BLOCK_SIZE multiple — this uniform stride is the slot pitch.
82	    // Multicast resolves receiver destinations as `issuer_base + r * stride`
83	    // and the LMEM model is block-addressed (byteen-masked), so a non-aligned
84	    // stride would truncate the destination; the descriptor handler rounds
85	    // its stride the same way to stay consistent.
86	    uint32_t stride = (pending_cta_.lmem_size + VX_CFG_MEM_BLOCK_SIZE - 1u)
87	                      & ~uint32_t(VX_CFG_MEM_BLOCK_SIZE - 1u);
88	    uint32_t max_slots = usable_slots(stride);
89	
90	    // Round-robin slot allocation over the usable range. Normalize the tail in
91	    // case a kernel transition shrank the usable count.
92	    if (tail_slot_ >= max_slots)
93	      tail_slot_ = 0;
94	    uint32_t base = tail_slot_;
95	
96	    // Cluster start: reserve K consecutive usable slots. Pre-wrap to 0 if the
97	    // window would overrun the usable range so the cluster stays contiguous
98	    // (members must occupy consecutive slots for multicast). All K must be free
99	    // up front so the following members never stall mid-cluster.
100	    uint32_t k = 1;
101	    if (pending_cta_.is_first_of_cluster) {
102	      k = pending_cta_.cluster_dim[0]
103	        * pending_cta_.cluster_dim[1]
104	        * pending_cta_.cluster_dim[2];
105	      if (k == 0) k = 1;
106	      if (base + k > max_slots)
107	        base = 0;
108	      if (k > max_slots)
109	        k = max_slots;  // cluster larger than co-residency: clamp (degenerate)
110	      for (uint32_t i = 0; i < k; ++i) {
111	        if (slot_rem_warps_[base + i] != 0)
112	          return false;  // window not free yet — wait
113	      }
114	    } else {
115	      // Standalone CTA, or a following cluster member (its slot was reserved by
116	      // the first-of-cluster window above and is guaranteed free).
117	      if (slot_rem_warps_[base] != 0)
118	        return false;
119	    }
120	
121	    // Reset Warp initialization states on kernel transitions
122	    if (pending_cta_.PC != cur_kernel_pc_) {
123	      cur_kernel_pc_ = pending_cta_.PC;
124	      for (uint32_t i = 0; i < num_warps_; ++i) {
125	        warp_init_mask_[i] = false;
126	      }
127	    }
128	
129	    // Accept the pending CTA into its slot.
130	    cta_ = pending_cta_;
131	    has_pending_ = false;
132	
133	    cta_size_       = (cta_.block_size + num_threads_ - 1) / num_threads_;
134	    rank_           = 0;
135	    block_size_rem_ = cta_.block_size;
136	    thread_idx_[0] = thread_idx_[1] = thread_idx_[2] = 0;
137	
138	    cur_slot_  = base;
139	    lmem_addr_ = lmem_base_ + uint64_t(base) * stride;
140	    slot_rem_warps_[base] = cta_size_;
141	    tail_slot_ = (base + 1) % max_slots;
142	
143	    has_cta_ = true;
144	  }
145	
146	  // Find lowest-index free warp slot.
147	  int free_wid = -1;
148	  for (int wid = 0; wid < (int)num_warps_; ++wid) {
149	    if (!active_warps.test(wid)) {
150	      free_wid = wid;
151	      break;
152	    }
153	  }
154	  if (free_wid < 0) return false;
155	
156	  if (!next_warp(!warp_init_mask_[free_wid], rec_out))
157	    return false;
158	
159	  // Mark warp as initialized
160	  warp_init_mask_[free_wid] = true;
161	
162	  wid_to_slot_[free_wid] = cur_slot_;
163	  *wid_out = uint32_t(free_wid);
164	  return true;
165	}
166	
167	void CtaDispatcher::warp_done(uint32_t wid) {
168	  uint32_t slot = wid_to_slot_[wid];
169	  if (slot >= num_warps_) return;  // not a CTA-dispatcher warp
170	  wid_to_slot_[wid] = num_warps_;  // clear assignment
171	  assert(slot_rem_warps_[slot] > 0);
172	  // When the last warp of a CTA exits, its slot (and the LMEM region at
173	  // slot × stride) frees immediately for reuse — no in-order reclaim.
174	  --slot_rem_warps_[slot];
175	}
176	
177	bool CtaDispatcher::next_warp(bool do_init, cta_warp_record_t* out) {
178	  if (!has_cta_) return false;
179	
180	  out->do_init  = do_init;
181	  out->PC       = Word(cta_.PC);
182	  out->entry    = Word(cta_.entry);
183	  out->mscratch = Word(cta_.param);
184	  out->param    = cta_.param;
185	  out->cta_id   = cur_slot_;
186	  out->cta_rank = rank_;
187	  out->cta_size = cta_size_;
188	
189	  out->thread_idx[0] = thread_idx_[0];
190	  out->thread_idx[1] = thread_idx_[1];
191	  out->thread_idx[2] = thread_idx_[2];
192	
193	  out->block_idx[0] = cta_.block_idx[0];
194	  out->block_idx[1] = cta_.block_idx[1];
195	  out->block_idx[2] = cta_.block_idx[2];
196	
197	  out->block_dim[0] = cta_.block_dim[0];
198	  out->block_dim[1] = cta_.block_dim[1];
199	  out->block_dim[2] = cta_.block_dim[2];
200	
201	  out->grid_dim[0] = cta_.grid_dim[0];
202	  out->grid_dim[1] = cta_.grid_dim[1];
203	  out->grid_dim[2] = cta_.grid_dim[2];
204	
205	  out->lmem_addr = lmem_addr_;
206	  out->cluster_size = cta_.cluster_dim[0] * cta_.cluster_dim[1] * cta_.cluster_dim[2];
207	
208	  // Thread mask: full warp or partial last warp.
209	  out->tmask.resize(num_threads_);
210	  uint32_t active = (block_size_rem_ >= num_threads_) ? num_threads_ : block_size_rem_;
211	  for (uint32_t t = 0; t < active; ++t) {
212	    out->tmask.set(t);
213	  }
214	
215	  // advance thread_idx with 3-D carry propagation (additive delta + carry)
216	  uint32_t next_x = thread_idx_[0] + cta_.warp_step[0];
217	  bool wrap_x = (next_x >= cta_.block_dim[0]);
218	  thread_idx_[0] = wrap_x ? (next_x - cta_.block_dim[0]) : next_x;
219	
220	  uint32_t next_y = thread_idx_[1] + cta_.warp_step[1] + (wrap_x ? 1 : 0);
221	  bool wrap_y = (next_y >= cta_.block_dim[1]);
222	  thread_idx_[1] = wrap_y ? (next_y - cta_.block_dim[1]) : next_y;
223	
224	  thread_idx_[2] = thread_idx_[2] + cta_.warp_step[2] + (wrap_y ? 1 : 0);
225	
226	  block_size_rem_ -= (block_size_rem_ >= num_threads_) ? num_threads_ : block_size_rem_;
227	
228	  ++rank_;
229	  if (rank_ >= cta_size_) {
230	    has_cta_ = false;
231	  }
232	
233	  return true;
234	}
