21	using namespace vortex;
22	
23	BarrierUnit::BarrierUnit(const SimContext& ctx, const char* name, Core* core, Scheduler* scheduler)
24	  : SimObject<BarrierUnit>(ctx, name)
25	  , core_(core)
26	  , scheduler_(scheduler)
27	  , barriers_(VX_CFG_NUM_WARPS * VX_CFG_NUM_BARRIERS)
28	{}
29	
30	BarrierUnit::~BarrierUnit() {}
31	
32	void BarrierUnit::on_reset() {
33	  for (auto& barrier : barriers_) {
34	    barrier.reset();
35	  }
36	}
37	
38	uint32_t BarrierUnit::get_phase(uint32_t bar_id) const {
39	  auto bar_index = bar_id & 0x7fffffff;
40	  return barriers_.at(bar_index).phase;
41	}
42	
43	void BarrierUnit::arrive(uint32_t bar_id, uint32_t count, uint32_t wid, bool is_sync_bar) {
44	  bool is_global = (bar_id >> 31);
45	  auto bar_index = bar_id & 0x7fffffff;
46	
47	  auto& barrier = barriers_.at(bar_index);
48	  const auto& active_warps = scheduler_->active_warps();
49	
50	  DP(4, "*** Barrier arrive: core #" << core_->id() << ", warp #" << wid << " at barrier #" << bar_id << ", phase=" << barrier.phase << ", wait_mask=" << barrier.wait_mask << ", count=" << barrier.count << ", events=" << barrier.events);
51	
52	  if (is_global) {
53	    barrier.count = count;
54	    // Track arrivals separately from waiters. Async arrive does NOT suspend
55	    // the warp, so it must not appear in wait_mask — otherwise global_resume
56	    // would wake it spuriously while it's mid-stalling-instruction.
57	    barrier.arrival_mask.set(wid);
58	    if (is_sync_bar) {
59	      barrier.wait_mask.set(wid);
60	    }
61	    if (barrier.arrival_mask.count() == active_warps.count() && barrier.events == 0) {
62	      // wait_mask is preserved across the async hop (holds warps resumed by
63	      // global_resume) and cleared there. arrival_mask is local-only and reset here.
64	      core_->socket()->global_barrier_arrive(bar_id, count, core_->id());
65	      barrier.arrival_mask.reset();
66	      barrier.count  = 0;
67	      barrier.events = 0;
68	    }
69	  } else {
70	    if (is_sync_bar) {
71	      barrier.wait_mask.set(wid);
72	    }
73	    // local barrier handling
74	    auto barrier_count_p1 = barrier.count + 1;
75	    if (barrier_count_p1 == count && barrier.events == 0) {
76	      // resume waiting warps
77	      for (uint32_t i = 0; i < VX_CFG_NUM_WARPS; ++i) {
78	        if (barrier.wait_mask.test(i)) {
79	          DP(3, "*** Resume core #" << core_->id() << ", warp #" << i << " at barrier #" << bar_id);
80	          scheduler_->resume(i);
81	        }
82	      }
83	      // reset barrier and advance phase
84	      barrier.wait_mask.reset();
85	      ++barrier.phase;
86	    }
87	    // update count and wrap around
88	    if (count == 0) {
89	      std::cout << "Error: barrier_arrive count=0: core=" << core_->id() << " wid=" << wid << " bar_id=0x" << std::hex << bar_id << std::dec << " bar_index=" << bar_index << " is_sync=" << is_sync_bar << std::endl;
90	      std::abort();
91	    }
92	    barrier.count = barrier_count_p1 % count;
93	  }
94	}
95	
96	bool BarrierUnit::wait(uint32_t bar_id, uint32_t phase, uint32_t wid) {
97	  auto bar_index = bar_id & 0x7fffffff;
98	
99	  auto& barrier = barriers_.at(bar_index);
100	  bool wait = (barrier.phase == phase);
101	
102	  DP(4, "*** Barrier wait: core #" << core_->id() << ", warp #" << wid << " at barrier #" << bar_id << ", wait=" << wait);
103	
104	  if (wait) {
105	    // add warp to wait list
106	    barrier.wait_mask.set(wid);
107	    DP(3, "*** Suspend core #" << core_->id() << ", warp #" << wid << " at barrier #" << bar_id);
108	  }
109	
110	  return wait;
111	}
112	
113	void BarrierUnit::global_resume(uint32_t bar_id) {
114	  auto bar_index = bar_id & 0x7fffffff;
115	  auto& barrier = barriers_.at(bar_index);
116	  // Only resume warps that actually suspended on this barrier (sync_bar or
117	  // bar_wait). Async bar_arrive leaves wait_mask empty so this is a no-op,
118	  // which is the correct semantics for fire-and-forget global barriers.
119	  for (uint32_t i = 0; i < VX_CFG_NUM_WARPS; ++i) {
120	    if (barrier.wait_mask.test(i)) {
121	      DP(3, "*** Resume core #" << core_->id() << ", warp #" << i << " at barrier #" << bar_id);
122	      scheduler_->resume(i);
123	    }
124	  }
125	  barrier.wait_mask.reset();
126	  ++barrier.phase;
127	}
128	
129	void BarrierUnit::event_attach(uint32_t bar_id, uint32_t count) {
130	  auto bar_index = bar_id & 0x7fffffff;
131	  auto& barrier = barriers_.at(bar_index);
132	  barrier.events += count;
133	}
134	
135	void BarrierUnit::event_release(uint32_t bar_id) {
136	  bool is_global = (bar_id >> 31);
137	  auto bar_index = bar_id & 0x7fffffff;
138	  auto& barrier = barriers_.at(bar_index);
139	  const auto& active_warps = scheduler_->active_warps();
140	  assert(barrier.events > 0);
141	  --barrier.events;
142	  if (barrier.events == 0) {
143	    if (is_global) {
144	      if (barrier.arrival_mask.count() == active_warps.count()) {
145	        uint32_t num_cores = barrier.count;
146	        // notify global barrier
147	        core_->socket()->global_barrier_arrive(bar_id, num_cores, core_->id());
148	        barrier.arrival_mask.reset();
149	        barrier.count  = 0;
150	        barrier.events = 0;
151	      }
152	    } else {
153	      if (barrier.count == 0) {
154	        // resume waiting warps
155	        for (uint32_t i = 0; i < VX_CFG_NUM_WARPS; ++i) {
156	          if (barrier.wait_mask.test(i)) {
157	            DP(3, "*** Resume core #" << core_->id() << ", warp #" << i << " at barrier #" << bar_id);
158	            scheduler_->resume(i);
159	          }
160	        }
161	        // reset barrier and advance phase
162	        barrier.wait_mask.reset();
163	        ++barrier.phase;
