111	// Per-core warp lifecycle owner: holds warp register state, barrier state,
112	// and the CTA dispatcher. All methods that read or mutate warp/barrier state
113	// live here.
114	class Scheduler : public SimObject<Scheduler> {
115	public:
116	  Scheduler(const SimContext& ctx, const char* name, Core* core);
117	  ~Scheduler();
