119	  // ----- Warp lifecycle -----
120	  instr_trace_t* schedule(const WarpMask& warp_mask);
121	  void suspend(uint32_t wid);
122	  void resume(uint32_t wid);
123	  // Advance the warp's PC by `inc` bytes (called at decode with 2 or 4
124	  // depending on is_rvc; mirrors RTL warp_pcs update on decode_sched_if).
125	  // Pass the trace whose decode is firing so a stale post-trap fetch
126	  // (trace->trap_epoch trails the warp's current trap_epoch_) can be
127	  // discarded without clobbering the trap-set mtvec.
128	  void advance_pc(const instr_trace_t* trace, uint32_t inc);
129	  bool running() const;
