134	  // ----- Fragment Work Distributor (RASTER dispatch v2, §4) -----
135	  // The per-core FWD turns rasterized quad-waves into launched fragment warps.
136	  // SfuUnit owns the raster-bus I/O and feeds ready waves here; injection
137	  // (activate_warp + LMEM payload seed) and epoch accounting live in the
138	  // scheduler because they touch warp lifecycle. See
139	  // docs/proposals/gfx_v2_fwd_simx_impl.md.
140	  struct FwdWave {
141	    ThreadMask tmask;
142	    std::array<graphics::frag_payload_t, VX_CFG_NUM_THREADS> payload;
143	    FwdWave() : tmask(VX_CFG_NUM_THREADS) {}
144	  };
145	  // Arm from the RASTER fragment-dispatch descriptor (RASTER_FRAG_* DCRs):
146	  // remember the FS entry PC and arg pointer the distributor launches each
147	  // fragment warp with. There is no driver warp in the push model — the raster
148	  // engine launches fragment warps directly.
149	  void fwd_arm(Word frag_entry, Word frag_param);
